<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="auth-page container"><form class="form-card" method="post" action="/register"><p class="eyebrow">Tài khoản</p><h1>Đăng ký</h1><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><?= Csrf::field() ?><label for="fullname">Họ và tên</label><input id="fullname" name="name" type="text" value="<?= ViewHelper::escape((string)($name ?? '')) ?>" required><label for="email">Email</label><input id="email" name="email" type="email" value="<?= ViewHelper::escape((string)($email ?? '')) ?>" required><label for="password">Mật khẩu</label><input id="password" name="password" type="password" minlength="8" required><label for="referral-code">Mã giới thiệu (nếu có)</label><input id="referral-code" name="referral_code" type="text" maxlength="20" value="<?= ViewHelper::escape((string)($_POST['referral_code'] ?? '')) ?>" placeholder="Ví dụ: MB000001"><button class="button button-primary" type="submit">Tạo tài khoản</button><p>Đã có tài khoản? <a href="/login">Đăng nhập</a></p></form></div>
